/* Refresh balances without disrupting forms, scanner state, or hidden tabs. */
(()=>{'use strict';let busy=false,last=0,failed=false;
function allowed(){return !window.RIJAA_DEMO&&serverMode&&principal&&['customer','owner','admin'].includes(principal.kind)&&!publicPage&&!requestBusy&&!(draft&&view==='design')&&!document.querySelector('dialog[open]')&&!document.hidden&&(principal.kind==='customer'||['overview','mycards','customers','employees','branches','operations','logs'].includes(view));}
async function refresh(force=false){if(busy||!allowed()||(!force&&Date.now()-last<10000))return;busy=true;try{const selected=db.shop,scope=db.scopedBusiness,oldView=view,oldRole=role;const j=await api('/api/state?shop='+encodeURIComponent(selected||'')+(scope?'&scope='+encodeURIComponent(scope):''));if(!allowed())return;const changed=JSON.stringify(j.db)!==JSON.stringify(db);if(changed){acceptServer(j);view=oldView;role=oldRole;render();}last=Date.now();failed=false;label();}catch(e){failed=true;label();if([401,403,404].includes(e.status)){principal=null;publicPage='login';render();toast('انتهت الجلسة أو تغيرت صلاحيات الوصول.');}}finally{busy=false;}}
function label(){const host=document.querySelector('.customer-card-panel,.main,main');if(!host||!principal||window.RIJAA_DEMO)return;let bar=document.querySelector('#live-state-status');if(!bar){bar=document.createElement('div');bar.id='live-state-status';bar.className='sub live-state-status';bar.innerHTML='<span aria-live="polite"></span> <button type="button" class="btn quiet small" data-live-refresh>تحديث البيانات ↻</button>';host.append(bar);}bar.querySelector('span').textContent=failed?'تعذر التحديث، بياناتك المعروضة قديمة.':last?'آخر تحديث '+new Date(last).toLocaleTimeString('ar-SA',{hour:'2-digit',minute:'2-digit'}):'تتحدث البيانات تلقائيًا أثناء عرض الصفحة.';}
setInterval(()=>refresh(),10000);window.addEventListener('focus',()=>refresh(true));document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh(true);});document.addEventListener('click',e=>{if(e.target.closest('[data-live-refresh]'))refresh(true);});const previous=render;render=function(){previous();if(allowed())label();};
})();
